#include <Arduino.h>

#include <stdint.h>
// Active-low momentary button. Pure logic: no GPIO, blocking delays or Wi-Fi.
class ButtonLogic {
 public:
  enum Action { None, White100, White50, Off };
  uint8_t mode = 0; // 0: single/double click; 1: consecutive clicks 100/50
  bool longOff = true;
  uint32_t doubleMs = 350;
  void reset(bool down, uint32_t now) {
    raw = stable = down; changed = pressedAt = releasedAt = now;
    pending = false; held = down; nextHalf = false;
  }
  Action tick(bool down, uint32_t now) {
    if (down != raw) { raw = down; changed = now; }
    if (raw != stable && uint32_t(now - changed) >= 35) {
      stable = raw;
      if (stable) { pressedAt = now; held = false; }
      else if (!held) {
        if (mode == 1) {
          Action a = nextHalf ? White50 : White100;
          nextHalf = !nextHalf; pending = false; return a;
        }
        if (pending && uint32_t(pressedAt - releasedAt) <= doubleMs) {
          pending = false; return White50;
        }
        pending = true; releasedAt = now;
      }
    }
    if (stable && !held && longOff && uint32_t(now - pressedAt) >= 1200) {
      held = true; pending = false; nextHalf = false; return Off;
    }
    if (pending && !raw && !stable && uint32_t(now - releasedAt) >= doubleMs) {
      pending = false; return White100;
    }
    return None;
  }
 private:
  bool raw = false, stable = false, pending = false, held = false, nextHalf = false;
  uint32_t changed = 0, pressedAt = 0, releasedAt = 0;
};

