51;color:#ffd0d0}.smallbtn{padding:8px 12px;font-size:12px}.row{display:flex;align-items:center;justify-content:space-between;margin:20px 0 10px;gap:10px}label{font-size:13px;color:#cbd7e8}output{font-size:19px;font-weight:650;color:var(--accent);font-variant-numeric:tabular-nums}input,select{font:inherit}input[type=range]{width:100%;accent-color:#b1d4ff;margin:4px 0 14px;height:28px}input[type=color]{width:100%;height:64px;background:#101723;border:1px solid var(--line);padding:6px;border-radius:12px}input[type=text],input[type=password],input[type=number],select{display:block;width:100%;color:var(--text);background:#0d1623;border:1px solid #35445b;border-radius:10px;padding:12px;margin:8px 0 14px}input[type=file]{max-width:100%;font-size:12px;margin:10px 0 15px;display:block}.check{display:flex;align-items:center;gap:10px;margin:15px 0;line-height:1.5}.check input{accent-color:#aaccff;width:18px;height:18px}.toggle{width:48px;height:28px;appearance:none;background:#3d4c62;border-radius:20px;position:relative;cursor:pointer}.toggle:before{content:"";position:absolute;left:4px;top:4px;width:20px;height:20px;border-radius:50%;background:#fff;transition:transform .15s}.toggle:checked{background:#5794d3}.toggle:checked:before{transform:translateX(20px)}.scenes{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.scene{min-height:56px}.status{font-size:12px;color:var(--muted);margin:12px 0}.status:before{content:"";display:inline-block;width:7px;height:7px;background:#72cfa9;border-radius:50%;margin-right:8px}.msg{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);background:#22364a;border:1px solid #4c6c8d;border-radius:14px;padding:13px 18px;max-width:92vw;font-size:13px;z-index:5;box-shadow:0 8px 40px #0008;display:none}.msg.error{background:#482730;border-color:#84515f}.message{white-space:pre-wrap;line-height:1.6;color:var(--blue);font-size:13px}.warn{background:#352b21;border:1px solid #66503b;border-radius:12px;padding:12px;color:#f1d4ad;font-size:13px;line-height:1.6}.sectionLabel{font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);margin:28px 0 12px}.meta{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.meta span{display:block;font-size:12px;color:var(--muted);margin-bottom:8px}.meta b{font-size:15px}code{background:#0c1521;padding:2px 5px;border-radius:5px;font-size:12px}hr{border:0;border-top:1px solid var(--line);margin:20px 0}footer{font-size:12px;line-height:1.8;color:var(--muted);margin-top:30px}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #93beff;outline-offset:3px}progress{width:100%;height:16px;accent-color:#a7cfff}
@media(max-width:650px){main{padding:24px 16px 85px}.grid{grid-template-columns:1fr}.quick{gap:8px}.quick button{padding:14px 10px;min-height:90px}.quick strong{font-size:26px}.card{padding:18px}.meta{grid-template-columns:1fr 1fr}header .link{padding:9px;font-size:12px}.scenes{grid-template-columns:repeat(2,1fr)}}
</style></head><body><main><header><div><div class="kicker">POOL LED / ADMIN</div><h1>Ustawienia.</h1><div class="sub">Sprzęt, przycisk, Wi-Fi i aktualizacje.</div></div><a class="link" href="/">&#8592; Sterowanie</a></header>
<div class="warn" id="demoWarn" hidden>To podglad pliku HTML. Nie jest polaczony z ESP32. Zapis i aktualizacje sa wylaczone.</div>
<div class="card meta"><div><span>Firmware</span><b id="fw">...</b></div><div><span>Adres</span><b id="ip">...</b></div><div><span>Pamiec paneli</span><b id="fs">...</b></div><div><span>Maks. BIN OTA</span><b id="otaMax">...</b></div></div>
<section class="card"><div class="tag">NAZWA / ADRES / WSPOLNY PANEL</div><h2>Ten sterownik.</h2><form id="identityForm"><div class="grid"><div><label for="deviceLabel">Nazwa w panelu, np. Lazienka</label><input id="deviceLabel" type="text" maxlength="48" required></div><div><label for="hostname">Adres: wpisz tylko nazwe przed .local</label><input id="hostname" type="text" pattern="[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])?" maxlength="32" required><p class="hint">Na przyklad: dom-led lub lazienka. Bez spacji i polskich znakow. Kazdy ESP musi miec inna nazwe.</p></div></div><label for="panelOrigin">Zezwol na sterowanie z tego wspolnego panelu</label><input id="panelOrigin" type="text" placeholder="http://dom-led.local"><p class="hint">Na module Lazienka wpisz adres, pod ktorym otwierasz panel na pierwszym ESP. Puste pole = tylko wlasny panel. Nie uzywaj adresu publicznego.</p><button class="primary" type="submit">Zapisz nazwe i uprawnienie panelu</button><p class="hint">Zmiana nazwy .local restartuje ESP. Zmien tez jego wpis na liscie innych modulow. Siec awaryjna: <b id="apName">...</b>.</p></form></section>
<section class="card"><div class="tag">POZOSTALE ESP / DO 8 DODATKOWYCH MODULOW</div><h2>Pomieszczenia.</h2><p class="hint">Ta lista jest zapisana na tym ESP i widoczna na kazdym telefonie otwierajacym jego panel. Wszystkie moduly polacz z domowym Wi-Fi, nie z oddzielnymi sieciami Setup.</p><div id="nodeList"></div><form id="nodeForm"><label for="nodeId">Miejsce na liscie</label><select id="nodeId"><option value="0">Modul 1</option><option value="1">Modul 2</option><option value="2">Modul 3</option><option value="3">Modul 4</option><option value="4">Modul 5</option><option value="5">Modul 6</option><option value="6">Modul 7</option><option value="7">Modul 8</option></select><div class="grid"><div><label for="nodeLabel">Etykieta, np. Lazienka</label><input id="nodeLabel" type="text" maxlength="48"></div><div><label for="nodeOrigin">Adres ESP, np. http://lazienka.local</label><input id="nodeOrigin" type="text" placeholder="http://lazienka.local"></div></div><div class="actions"><button type="submit">Zapisz / zmien modul</button><button id="removeNode" type="button">Usun wybrane miejsce</button></div></form><p class="hint">Nie dodawaj tego samego ESP drugi raz. Ustawienia i aktualizacje kazdego modulu otwierasz bezposrednio przez jego link. Nie sa przekazywane hasla administratorow.</p></section><form id="configForm"><div class="grid" style="margin-top:18px"><section class="card"><div class="head"><div><div class="tag">01 / KONFIGURACJA</div><h2>Paski LED</h2></div></div>
<label for="rgbDrivers">RGB: liczba ukladow WS2811</label><input id="rgbDrivers" type="number" min="1" max="400" required>
<label for="whiteDrivers">Bialy: liczba ukladow WS2811</label><input id="whiteDrivers" type="number" min="1" max="400" required>
<label for="whiteMode">Adresowanie bialego</label><select id="whiteMode"><option value="1">1 sekcja / uklad</option><option value="3">3 sekcje / uklad</option></select>
<label for="rgbOrder">Kolejnosc kolorow RGB</label><select id="rgbOrder"><option value="0">RGB (dotychczasowa)</option><option value="1">GRB</option><option value="2">BRG</option><option value="3">RBG</option><option value="4">GBR</option><option value="5">BGR</option></select>
<label class="check"><input id="restoreBoot" type="checkbox">Po restarcie przywroc ostatnie swiatlo</label>
<p class="hint">D0 / GPIO1: RGB. D1 / GPIO2: bialy. Liczba ukladow to nie liczba pojedynczych diod COB.</p></section>
<section class="card"><div class="head"><div><div class="tag">02 / STEROWANIE FIZYCZNE</div><h2>Przycisk</h2></div></div>
<label class="check"><input id="buttonEnabled" type="checkbox">Włącz przycisk na D3 / GPIO4</label>
<label for="buttonMode">Sposob naciskania</label><select id="buttonMode"><option value="0">Klik: 100% / dwuklik: 50%</option><option value="1">Kolejne klikniecia: 100% &#8594; 50% &#8594; 100%</option></select>
<label class="check"><input id="longOff" type="checkbox">Przytrzymanie 1,2 s: wszystko wylacz</label>
<p class="hint">Obie sceny biale gasza RGB i zatrzymuja animacje bialego. W trybie dwukliku pojedyncze klikniecie ma opoznienie ok. 0,35 s, aby nie bylo blysku 100% przed 50%.</p>
<div class="warn">Przycisk chwilowy NO, bez napiecia:<br><b>D3 &#8212; przycisk &#8212; GND</b><br>Nie podlaczaj 5 V, 24 V ani 230 V do tego wejscia.</div>
</section></div><div class="actions"><button class="primary" type="submit">Zapisz konfiguracje paskow i przycisku</button></div></form>
<section class="card"><div class="tag">03 / SIEC</div><h2>Wi-Fi</h2><p class="hint">Zmiana wymaga restartu. Puste SSID: tylko siec PoolLED-Setup-xxxxxx. Brak routera: awaryjny punkt dostepowy.</p>
<form id="wifiForm"><div class="grid"><div><label for="ssid">Nazwa domowej sieci 2,4 GHz</label><input id="ssid" type="text" maxlength="32" autocomplete="off"></div><div><label for="wifiPassword">Nowe hasło Wi-Fi (puste = bez zmian)</label><input id="wifiPassword" type="password" maxlength="63" autocomplete="new-password"></div></div>
<label class="check"><input id="openNetwork" type="checkbox">Ta siec nie ma hasla</label>
<label for="apPassword">Nowe hasło sieci awaryjnej PoolLED-Setup-xxxxxx (puste = bez zmian)</label><input id="apPassword" type="password" minlength="8" maxlength="63" autocomplete="new-password">
<button type="submit">Zapisz Wi-Fi i uruchom ponownie</button></form></section>
<div class="sectionLabel">Aktualizacje - dwa rozne rodzaje plikow</div>
<div class="grid"><section class="card"><div class="tag">04 / BEZ KOMPILOWANIA</div><h2>Wyglad panelu</h2><p class="hint">Wgraj pojedynczy HTML z wbudowanym CSS i JavaScript. Obslugiwane API: 2. Maksymalnie 96 KiB. Nie przesylaj ZIP-a.</p>
<label for="pageTarget">Ktory panel zmieniasz?</label><select id="pageTarget"><option value="control">Sterowanie /</option><option value="settings">Ustawienia /settings</option></select>
<label for="htmlFile">Nowy plik HTML</label><input id="htmlFile" type="file" accept=".html,.htm,text/html"><button class="primary" id="uploadHTML" type="button">Wgraj panel HTML</button>
<p class="hint">Przy pierwszym uzyciu moze byc potrzebne przygotowanie pamieci ponizej. Panel ratunkowy <code>/service</code> pozostaje w firmware i nie jest podmieniany.</p></section>
<section class="card"><div class="tag">05 / PRZEZ WI-FI</div><h2>Program ESP32</h2><p class="hint">Nowe funkcje procesora wymagaja skompilowanego BIN-a aplikacji. Po poprawnym zapisie sterownik zrestartuje sie.</p>
<div class="warn"><b>OTA: tylko BIN aplikacji.</b><br>Nie wgrywaj tutaj <code>0x0-merged-firmware.bin</code>, bootloadera ani tablicy partycji. Połączony obraz jest do esptool-js przez USB.</div>
<label for="binFile">BIN aplikacji ESP32-S3</label><input id="binFile" type="file" accept=".bin,application/octet-stream"><button class="primary" id="uploadBIN" type="button">Aktualizuj firmware</button></section></div>
<section class="card"><progress id="progress" max="100" value="0" aria-label="Postep wysylania"></progress><div class="message" id="uploadMessage" role="status">Gotowe. Uzywaj tylko zaufanych plikow i lokalnej sieci Wi-Fi.</div></section>
<section class="card"><h2>Administrator i odzyskiwanie</h2><form id="passwordForm"><div class="row"><label for="adminPassword">Nowe hasło administratora (login: admin)</label></div><input id="adminPassword" type="password" minlength="8" maxlength="64" autocomplete="new-password" required><button type="submit">Zmien hasło</button></form><hr>
<div class="actions"><button id="formatFS" type="button">Przygotuj / wyczysc pamiec paneli</button><button id="resetUI" type="button">Przywróć wbudowany wyglad</button><button id="restart" type="button">Restart ESP</button></div>
<p class="hint">Wyczyszczenie pamieci paneli usuwa tylko wgrane strony, nie ustawienia LED. Gdy nowy panel nie dziala, otworz <code>/service</code>.<br>Hasło chroni ustawienia i aktualizacje. Zwykle sterowanie pozostaje dostepne dla osob w tej samej sieci. Nie przekierowuj portow routera na ESP.</p></section>
<footer id="health"></footer></main><div id="toast" class="msg" role="status" aria-live="polite"></div><script>
const $=id=>document.getElementById(id); const demo=location.protocol==='file:';
let toastTimer;
function note(t,error=false){$('toast').textContent=t;$('toast').className='msg'+(error?' error':'');$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',6500)}
async function request(url,fields,token=''){
 const headers={'X-PoolLED':'2'};if(token)headers['X-CSRF-Token']=token;
 const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),7000);
 const options={cache:'no-store',credentials:'same-origin',headers,signal:controller.signal};
 if(fields!==undefined){options.method='POST';options.body=new URLSearchParams(fields)}
 let r;try{r=await fetch(url,options)}finally{clearTimeout(timer)}if(!r.ok)throw Error((await r.text())||('HTTP '+r.status));
 return (r.headers.get('Content-Type')||'').includes('application/json')?r.json():r.text();
}

const safeOrigin=s=>/^http:\/\/(?:[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])?\.local|(?:\d{1,3}\.){3}\d{1,3})$/.test(s);
let token='',admin={},uploading=false;
async function load(){
 try{
  admin=demo?{version:'2.1.0',ip:'192.168.4.1',fsReady:1,fsTotal:1441792,fsUsed:0,otaMax:1310720,rgbDrivers:60,whiteDrivers:60,whiteMode:1,rgbOrder:0,buttonEnabled:1,buttonMode:0,longOff:1,restoreBoot:1,hostname:'dom-led',label:'Dom',panelOrigin:'',apName:'PoolLED-Setup-a1b2c3',ssid:'',heap:180000,uptime:120}:await request('/api/admin');
  token=admin.token||'';
  $('hostname').value=admin.hostname;$('deviceLabel').value=admin.label;$('panelOrigin').value=admin.panelOrigin;$('apName').textContent=admin.apName;
  await loadNodes();
  for(const id of ['rgbDrivers','whiteDrivers','whiteMode','rgbOrder','buttonMode','ssid'])$(id).value=admin[id];
  for(const id of ['buttonEnabled','longOff','restoreBoot'])$(id).checked=!!admin[id];
  $('fw').textContent=admin.version;$('ip').textContent=admin.ip;
  $('fs').textContent=admin.fsReady?Math.round((admin.fsTotal-admin.fsUsed)/1024)+' KiB wolne':'Nieprzygotowana';
  $('otaMax').textContent=admin.otaMax?Math.round(admin.otaMax/1024)+' KiB':'Brak partycji OTA';
  $('health').textContent='Czas pracy: '+admin.uptime+' s / Wolny RAM: '+Math.round(admin.heap/1024)+' KiB / API 2';
 }catch(e){note(e.message,true)}
}
async function post(url,fields){if(demo)throw Error('To tylko podglad - zmiana nie zostala wyslana');return request(url,fields,token)}
$('configForm').onsubmit=async e=>{e.preventDefault();try{note(await post('/api/config',{rgb:$('rgbDrivers').value,white:$('whiteDrivers').value,mode:$('whiteMode').value,order:$('rgbOrder').value,enabled:$('buttonEnabled').checked?1:0,buttonMode:$('buttonMode').value,longOff:$('longOff').checked?1:0,restore:$('restoreBoot').checked?1:0}))}catch(e){note(e.message,true)}};
$('wifiForm').onsubmit=async e=>{e.preventDefault();if(!confirm('Zapisac siec i zrestartowac ESP?'))return;try{note(await post('/api/wifi',{ssid:$('ssid').value,password:$('wifiPassword').value,open:$('openNetwork').checked?1:0,apPassword:$('apPassword').value}))}catch(e){note(e.message,true)}};
$('passwordForm').onsubmit=async e=>{e.preventDefault();try{note(await post('/api/password',{password:$('adminPassword').value}));$('adminPassword').value=''}catch(e){note(e.message,true)}};
$('formatFS').onclick=async()=>{if(!confirm('Usunac wszystkie wgrane panele HTML i przygotowac pamiec? Wbudowane panele i ustawienia LED pozostana.'))return;try{note(await post('/api/fs/format',{confirm:'FORMAT'}));await load()}catch(e){note(e.message,true)}};
$('resetUI').onclick=async()=>{if(!confirm('Przywróćic wbudowane panele?'))return;try{note(await post('/api/ui/reset',{}))}catch(e){note(e.message,true)}};
$('restart').onclick=async()=>{if(!confirm('Zrestartowac ESP?'))return;try{note(await post('/api/reboot',{}))}catch(e){note(e.message,true)}};
function upload(url,file){return new Promise((resolve,reject)=>{
 const x=new XMLHttpRequest();x.open('POST',url);x.setRequestHeader('X-PoolLED','2');x.setRequestHeader('X-CSRF-Token',token);x.timeout=180000;
 x.upload.onprogress=e=>{if(e.lengthComputable)$('progress').value=Math.round(e.loaded/e.total*100)};
 x.onload=()=>x.status>=200&&x.status<300?resolve(x.responseText):reject(Error(x.responseText||('HTTP '+x.status)));
 x.onerror=()=>reject(Error('Utracono polaczenie. Sprawdz, czy ESP jest nadal dostepne.'));
 x.ontimeout=()=>reject(Error('Limit czasu. Nie ponawiaj przed sprawdzeniem stanu ESP.'));
 const data=new FormData();data.append('file',file,file.name);x.send(data);
})}
async function doUpload(kind){
 if(demo){note('To podglad. Otwórz panel na ESP, aby wgrac plik.',true);return}if(uploading)return;
 const file=$(kind==='html'?'htmlFile':'binFile').files[0];if(!file){note('Najpierw wybierz plik',true);return}
 try{
  let url;
  if(kind==='html'){
   if(!admin.fsReady)throw Error('Najpierw kliknij Przygotuj / wyczysc pamiec paneli');
   if(file.size>98304)throw Error('Maksymalny rozmiar HTML: 96 KiB');
   const head=await file.slice(0,2048).text();if(!head.includes('name="poolled-api" content="2"'))throw Error('Brak znacznika poolled-api 2 w HTML');
   url='/api/ui/upload?page='+$('pageTarget').value+'&size='+file.size;
  }else{
   const bytes=new Uint8Array(await file.slice(0,288).arrayBuffer());
   if(bytes.length<288||bytes[0]!==233||(bytes[12]|bytes[13]<<8)!==9||new DataView(bytes.buffer).getUint32(32,true)!==0xabcd5432)throw Error('To nie BIN aplikacji ESP32-S3. Plik merged/0x0 jest tylko do USB.');
   if(!admin.otaMax||file.size>admin.otaMax)throw Error('BIN jest za duzy dla obecnej partycji OTA.');
   if(!confirm('Wgrac nowy program ESP32? Nie odlaczaj zasilania podczas aktualizacji.'))return;
   url='/api/firmware?size='+file.size;
  }
  uploading=true;$('uploadBIN').disabled=$('uploadHTML').disabled=true;$('progress').value=0;
  $('uploadMessage').textContent='Wysylanie. Nie odlaczaj zasilania i nie zamykaj strony...';
  const result=await upload(url,file);$('uploadMessage').textContent=result;note(result);
 }catch(e){$('uploadMessage').textContent=e.message;note(e.message,true)}finally{uploading=false;$('uploadBIN').disabled=$('uploadHTML').disabled=false}
}
$('uploadHTML').onclick=()=>doUpload('html');$('uploadBIN').onclick=()=>doUpload('bin');
if(demo){$('demoWarn').hidden=false;document.querySelector('a.link').href='panel.html'}

let nodeRows=[];
async function loadNodes(){
 const d=demo?{nodes:[{id:0,label:'Lazienka',origin:'http://lazienka.local'}]}:await request('/api/devices');nodeRows=d.nodes;
 $('nodeList').replaceChildren();
 if(!nodeRows.length)$('nodeList').textContent='Brak innych modulow. Dodaj drugi ESP ponizej.';
 for(const n of nodeRows){const row=document.createElement('p');row.className='hint';row.textContent=(n.id+1)+'. '+n.label+' / '+n.origin+' ';
  if(safeOrigin(n.origin)){const a=document.createElement('a');a.textContent='Otwórz ustawienia';a.href=demo?'settings.html':n.origin+'/settings';a.target='_blank';a.rel='noopener';row.append(a)}$('nodeList').append(row)}
 fillNode();
}
function fillNode(){const n=nodeRows.find(n=>n.id===Number($('nodeId').value));$('nodeLabel').value=n?n.label:'';$('nodeOrigin').value=n?n.origin:''}
$('nodeId').onchange=fillNode;
$('identityForm').onsubmit=async e=>{e.preventDefault();if($('hostname').value!==admin.hostname&&!confirm('Zmiana adresu restartuje ESP. Potem otworz http://'+$('hostname').value+'.local/ . Kontynuowac?'))return;
 try{note(await post('/api/identity',{hostname:$('hostname').value,label:$('deviceLabel').value,panelOrigin:$('panelOrigin').value}))}catch(e){note(e.message,true)}};
$('nodeForm').onsubmit=async e=>{e.preventDefault();try{note(await post('/api/node',{id:$('nodeId').value,label:$('nodeLabel').value,origin:$('nodeOrigin').value}));await loadNodes()}catch(e){note(e.message,true)}};
