bool uploadBusy = false, rebootPending = false, mdnsStarted = false;
uint32_t dirtyTime = 0, lastFrame = 0, rebootAt = 0, lastReconnect = 0;
String adminPassword, csrfToken, apPassword;
ButtonLogic button;

