void reply(int code, const String &text) {
  server.sendHeader("Cache-Control", "no-store");
  server.sendHeader("X-Content-Type-Options", "nosniff");
  server.send(code, "text/plain; charset=utf-8", text);
}
bool isAdmin() { return adminPassword.length() >= 8 && server.authenticate("admin", adminPassword.c_str()); }
bool requireAdmin() {
  if (adminPassword.length() < 8) { reply(403, "Najpierw otworz /settings i ustaw haslo administratora."); return false; }
  if (!isAdmin()) { server.requestAuthentication(DIGEST_AUTH, "PoolLED", "Wymagane logowanie administratora"); return false; }
  return true;
}
bool acceptControlOrigin();
bool sameOrigin();
bool requireWrite(bool admin = false) {
  if (admin) { if (!sameOrigin()) { reply(403,"Ustawienia tylko bezposrednio na tym ESP"); return false; } }
  else if (!acceptControlOrigin()) return false;
  if (admin && !requireAdmin()) return false;
  if (server.header("X-PoolLED") != "2") { reply(403, "Brak naglowka X-PoolLED: 2"); return false; }
  if (admin && server.header("X-CSRF-Token") != csrfToken) { reply(403, "Odswiez panel: nieprawidlowy token"); return false; }
  return true;
}
bool uploadAuthorized() {
  return sameOrigin() && isAdmin() && server.header("X-PoolLED") == "2" && server.header("X-CSRF-Token") == csrfToken;
}
String jsonString(const String &s) {
  String r = "\"";
  for (size_t i=0; i<s.length(); ++i) {
    unsigned char c = s[i];
    if (c == '"' || c == '\\') { r += '\\'; r += char(c); }
    else if (c < 32) { char x[7]; snprintf(x, sizeof(x), "\\u%04x", c); r += x; }
    else r += char(c);
  }
  return r + "\"";
}
void jsonReply(const String &s) {
  server.sendHeader("Cache-Control", "no-store");
  server.send(200, "application/json; charset=utf-8", s);
}
String currentIP() { return WiFi.status()==WL_CONNECTED ? WiFi.localIP().toString() : WiFi.softAPIP().toString(); }
String stateJSON() {
  char color[8]; snprintf(color, sizeof(color), "#%06lX", (unsigned long)(st.rgbColor & 0xFFFFFF));
  String s; s.reserve(500);
  s = "{\"api\":2,\"version\":" + jsonString(VERSION);
  s += ",\"rgbOn\":" + String(st.rgbOn) + ",\"whiteOn\":" + String(st.whiteOn);
  s += ",\"rgbBrightness\":" + String(st.rgbBrightness) + ",\"whiteBrightness\":" + String(st.whiteBrightness);
  s += ",\"rgbColor\":" + jsonString(color);
  s += ",\"rgbEffect\":" + String(st.rgbEffect) + ",\"whiteEffect\":" + String(st.whiteEffect);
  s += ",\"speed\":" + String(st.speed) + ",\"ip\":" + jsonString(currentIP());
  s += ",\"apMode\":" + String(WiFi.status()==WL_CONNECTED ? 0 : 1);
  s += ",\"label\":" + jsonString(deviceLabel) + ",\"hostname\":" + jsonString(hostname) + "}";
  return s;
}

// Local names and URLs only. Never accept a script, external site or arbitrary path.
bool validHostname(const String &s) {
  if (s.length()<1 || s.length()>32 || s[0]=='-' || s[s.length()-1]=='-') return false;
  for (size_t i=0;i<s.length();++i) if (!((s[i]>='a'&&s[i]<='z')||(s[i]>='0'&&s[i]<='9')||s[i]=='-')) return false;
  return true;
}
bool validLabel(const String &s) {
  if (s.isEmpty() || s.length()>48) return false;
  for (size_t i=0;i<s.length();++i) if ((unsigned char)s[i]<32) return false;
  return true;
}
String normalizeOrigin(String s) {
  s.trim(); s.toLowerCase();
  if (s.isEmpty()) return "";
  if (!s.startsWith("http://")) s="http://"+s;
  if (s.endsWith("/")) s.remove(s.length()-1);
  if (s.endsWith(":80")) s.remove(s.length()-3);
  return s;
}
bool validOrigin(const String &s) {
  if (!s.startsWith("http://")) return false;
  String h=s.substring(7);
  if (h.endsWith(".local")) return validHostname(h.substring(0,h.length()-6));
  IPAddress ip;
  if (!ip.fromString(h) || h!=ip.toString()) return false;
  return ip[0]==10 || (ip[0]==172 && ip[1]>=16 && ip[1]<=31) || (ip[0]==192 && ip[1]==168);
}
bool sameOrigin() {
  String origin=server.header("Origin");
  return origin.isEmpty() || origin==String("http://")+server.hostHeader();
}
bool acceptControlOrigin() {
  if (sameOrigin()) return true;
  String origin=server.header("Origin");
  if (!allowedPanelOrigin.isEmpty() && origin==allowedPanelOrigin) {
    server.sendHeader("Access-Control-Allow-Origin",origin);
    server.sendHeader("Vary","Origin");
    return true;
  }
  reply(403,"Ten panel nie jest dozwolony. Na tym ESP ustaw Adres wspolnego panelu."); return false;
}
void corsPreflight() {
  if (!acceptControlOrigin()) return;
  server.sendHeader("Access-Control-Allow-Methods","GET, POST, OPTIONS");
  server.sendHeader("Access-Control-Allow-Headers","X-PoolLED, Content-Type");
  server.sendHeader("Access-Control-Max-Age","300");
  server.send(204,"text/plain","");
}
void devicesJSON() {
  String s="{\"api\":2,\"self\":{\"label\":"+jsonString(deviceLabel)+",\"hostname\":"+jsonString(hostname)+"},\"nodes\":[";
  bool first=true;
  for (uint8_t i=0;i<MAX_NODES;++i) if (!nodes[i].origin.isEmpty()) {
    if (!first) s+=","; first=false;
    s+="{\"id\":"+String(i)+",\"label\":"+jsonString(nodes[i].label)+",\"origin\":"+jsonString(nodes[i].origin)+"}";
  }
  jsonReply(s+"]}");
}
void apiIdentity() {
  if (!requireWrite(true)) return;
  String h=server.arg("hostname"), label=server.arg("label"); h.trim(); h.toLowerCase(); label.trim();
  String origin=normalizeOrigin(server.arg("panelOrigin"));
  if (!validHostname(h)||!validLabel(label)||(!origin.isEmpty()&&!validOrigin(origin))) {
    reply(400,"Nazwa hosta: 1-32 male litery a-z, cyfry i lacznik; etykieta do 48 bajtow; panel: http://nazwa.local lub lokalny IPv4."); return;
  }
  bool reboot=h!=hostname;
  if (prefs.putString("hostname",h)==0 || prefs.putString("label",label)==0) { reply(500,"Blad zapisu nazwy"); return; }
  prefs.putString("panelOrigin",origin);
  deviceLabel=label; allowedPanelOrigin=origin;
  if (settingsDirty) saveSettings();
  reply(200,reboot?String("Zapisano. Restart. Nowy adres: http://")+h+".local/ . Zaktualizuj tez nazwe w innych modulach.":"Zapisano nazwe i dostep wspolnego panelu.");
  if (reboot) { rebootPending=true; rebootAt=millis()+1200; }
}
void apiNode() {
  if (!requireWrite(true)) return;
  String idArg=server.arg("id");
  if (idArg.length()!=1||idArg[0]<'0'||idArg[0]>='0'+MAX_NODES) { reply(400,"Nieprawidlowy numer modulu"); return; }
  uint8_t i=idArg[0]-'0';
  String origin=normalizeOrigin(server.arg("origin")), label=server.arg("label"); label.trim();
  if (!origin.isEmpty() && (!validOrigin(origin)||!validLabel(label))) { reply(400,"Podaj etykiete i lokalny adres .local lub IPv4"); return; }
  if (origin==String("http://")+hostname+".local" || origin==String("http://")+currentIP()) { reply(400,"Ten sterownik jest juz na liscie jako lokalny"); return; }
  for (uint8_t j=0;j<MAX_NODES;++j) if (j!=i&&!origin.isEmpty()&&nodes[j].origin==origin) { reply(400,"Ten modul jest juz na liscie"); return; }
  String key="node"+String(i);
  prefs.putString((key+"url").c_str(),origin); prefs.putString((key+"name").c_str(),origin.isEmpty()?"":label);
  nodes[i].origin=origin; nodes[i].label=origin.isEmpty()?"":label;
  reply(200,origin.isEmpty()?"Modul usuniety z tego panelu":"Modul zapisany. Zezwol na adres tego panelu w ustawieniach dodanego ESP.");
}
void loadNetworkSettings() {
  char suffix[7]; snprintf(suffix,sizeof(suffix),"%06lx",(unsigned long)((ESP.getEfuseMac()>>24)&0xFFFFFF));
  hostname=prefs.getString("hostname",String("led-")+suffix);
  if (!validHostname(hostname)) hostname=String("led-")+suffix;
  deviceLabel=prefs.getString("label","Moje swiatlo");
  if (!validLabel(deviceLabel)) deviceLabel="Moje swiatlo";
  apName=String("PoolLED-Setup-")+suffix;
  allowedPanelOrigin=normalizeOrigin(prefs.getString("panelOrigin",""));
  if (!allowedPanelOrigin.isEmpty()&&!validOrigin(allowedPanelOrigin)) allowedPanelOrigin="";
  for (uint8_t i=0;i<MAX_NODES;++i) {
    String key="node"+String(i);
    nodes[i].label=prefs.getString((key+"name").c_str(),"");
    nodes[i].origin=normalizeOrigin(prefs.getString((key+"url").c_str(),""));
    if (!validOrigin(nodes[i].origin)||!validLabel(nodes[i].label)) nodes[i].origin="";
  }
}
void beginMDNS() {
  if (mdnsStarted) MDNS.end();
  mdnsStarted=MDNS.begin(hostname.c_str());
  if (mdnsStarted) { MDNS.addService("http","tcp",80); MDNS.addServiceTxt("http","tcp","app","poolled"); }
}

void clampState() {
  st.rgbColor &= 0xFFFFFF;
  st.rgbBrightness = constrain(st.rgbBrightness, 0, 100);
  st.whiteBrightness = constrain(st.whiteBrightness, 0, 100);
  st.speed = constrain(st.speed, 1, 100);
  st.rgbEffect = constrain(st.rgbEffect, 0, 4);
  st.whiteEffect = constrain(st.whiteEffect, 0, 3);
  st.rgbOn = st.rgbOn ? 1 : 0; st.whiteOn = st.whiteOn ? 1 : 0;
}
void changed(bool rgb = true, bool white = true) {
  settingsDirty = true; dirtyTime = millis(); rgbDirty |= rgb; whiteDirty |= white;
}
void saveSettings() {
  prefs.putBytes("light", &st, sizeof(st));
  prefs.putUShort("rgbN", rgbDrivers); prefs.putUShort("whiteN", whiteDrivers);
  prefs.putUChar("whiteM", whiteMode); prefs.putUChar("rgbOrder", rgbOrder);
  prefs.putBool("btnEnable", buttonEnabled); prefs.putUChar("btnMode", button.mode);
  prefs.putBool("btnLong", button.longOff); prefs.putBool("restore", restoreBoot);
  settingsDirty = false; rgbDirty=whiteDirty=true;
}
void whiteScene(uint8_t brightness) {
  st.rgbOn = 0; st.whiteOn = brightness > 0; st.whiteBrightness = brightness;
  st.whiteEffect = 0; changed();
}
void allOff() { st.rgbOn = st.whiteOn = 0; changed(); }
void pollButton() {
  if (!buttonEnabled || uploadBusy) return;
  switch (button.tick(digitalRead(PIN_BUTTON) == LOW, millis())) {
    case ButtonLogic::White100: whiteScene(100); break;
    case ButtonLogic::White50: whiteScene(50); break;
    case ButtonLogic::Off: allOff(); break;
    default: break;
  }
}
void configureStrips() {
  // Clear the OLD lengths once, so reducing a length cannot leave trailing LEDs on.
  rgbStrip.clear(); whiteStrip.clear(); rgbStrip.show(); whiteStrip.show();
  const neoPixelType orders[] = {NEO_RGB, NEO_GRB, NEO_BRG, NEO_RBG, NEO_GBR, NEO_BGR};
  rgbStrip.updateType(orders[rgbOrder] + NEO_KHZ800);
  rgbStrip.updateLength(rgbDrivers); whiteStrip.updateLength(whiteDrivers);
  rgbStrip.begin(); whiteStrip.begin(); rgbDirty = whiteDirty = true;
}
float effectLevel(uint8_t effect, uint16_t i, uint16_t count, uint32_t now) {
  if (!effect) return 1.0f;
  float speed = st.speed / 42.0f;
  if (effect == 2) return 0.10f + 0.90f * (0.5f + 0.5f * sinf(now * 0.004f * speed));
  if (effect == 1) {
    uint32_t stepMs = 550UL / (1UL + st.speed / 10UL);
    uint16_t head = (now / stepMs) % count;
    uint16_t distance = (i + count - head) % count;
    uint16_t trail = count / 10; if (!trail) trail = 1;
    return distance < trail ? 1.0f : 0.02f;
  }
  float pos = 12.5663706f * i / count;
  return 0.08f + 0.92f * (0.5f + 0.5f * sinf(pos - now * 0.0025f * speed));
}
uint8_t lit(uint8_t percent, float fraction) {
  float v = 255.0f * percent * fraction / 100.0f;
  return v <= 0 ? 0 : v >= 255 ? 255 : static_cast<uint8_t>(v + 0.5f);
}
void renderFrame(bool rgb, bool white) {
  uint32_t now = millis();
  if (rgb) {
    for (uint16_t i=0; i<rgbDrivers; ++i) {
      if (!st.rgbOn || !st.rgbBrightness) { rgbStrip.setPixelColor(i, 0); continue; }
      if (st.rgbEffect == 1) {
        uint16_t hue = now * (st.speed + 2UL) / 12UL + uint32_t(i) * 65535UL / rgbDrivers;
        rgbStrip.setPixelColor(i, Adafruit_NeoPixel::ColorHSV(hue, 255, lit(st.rgbBrightness, 1)));
      } else {
        uint8_t mode = st.rgbEffect == 2 ? 1 : st.rgbEffect == 3 ? 2 : st.rgbEffect == 4 ? 3 : 0;
        uint8_t b = lit(st.rgbBrightness, effectLevel(mode, i, rgbDrivers, now));
        uint32_t c = st.rgbColor;
        rgbStrip.setPixelColor(i, ((c>>16)&255)*b/255, ((c>>8)&255)*b/255, (c&255)*b/255);
      }
    }
    rgbStrip.show(); rgbDirty = false;
  }
  if (white) {
    uint16_t count = whiteDrivers * (whiteMode == 3 ? 3 : 1);
    for (uint16_t i=0; i<whiteDrivers; ++i) {
      uint8_t channels[3];
      for (uint8_t c=0; c<3; ++c) {
        uint16_t index = whiteMode == 3 ? i*3+c : i;
        channels[c] = st.whiteOn ? lit(st.whiteBrightness, effectLevel(st.whiteEffect, index, count, now)) : 0;
      }
      whiteStrip.setPixelColor(i, channels[0], channels[1], channels[2]);
    }
    whiteStrip.show(); whiteDirty = false;
  }
}
void apiSet() {
  if (!requireWrite()) return;
  String color=server.arg("color");
  if (server.hasArg("color")) {
    if (color.length()!=6) { reply(400,"Kolor: szesc cyfr HEX"); return; }
    for (size_t i=0;i<6;++i) if (!isxdigit(color[i])) { reply(400,"Nieprawidlowy kolor"); return; }
  }
  bool r=false, w=false;
  if (server.hasArg("rb")) { st.rgbBrightness=constrain(server.arg("rb").toInt(),0,100); r=true; }
  if (server.hasArg("wb")) { st.whiteBrightness=constrain(server.arg("wb").toInt(),0,100); w=true; }
  if (server.hasArg("re")) { st.rgbEffect=constrain(server.arg("re").toInt(),0,4); r=true; }
  if (server.hasArg("we")) { st.whiteEffect=constrain(server.arg("we").toInt(),0,3); w=true; }
  if (server.hasArg("ron")) { st.rgbOn=server.arg("ron").toInt()!=0; r=true; }
  if (server.hasArg("won")) { st.whiteOn=server.arg("won").toInt()!=0; w=true; }
  if (server.hasArg("sp")) { st.speed=constrain(server.arg("sp").toInt(),1,100); r=w=true; }
  if (server.hasArg("color")) {
    String c=server.arg("color");
    if (c.length()!=6) { reply(400,"Kolor: szesc cyfr HEX"); return; }
    for (size_t i=0;i<6;i++) if (!isxdigit(c[i])) { reply(400,"Nieprawidlowy kolor"); return; }
    st.rgbColor=strtoul(c.c_str(),nullptr,16); r=true;
  }
  if (r||w) changed(r,w); jsonReply(stateJSON());
}
void apiPreset() {
  if (!requireWrite()) return;
  String name=server.arg("name");
  if (name=="day" || name=="white100") whiteScene(100);
  else if (name=="white50") whiteScene(50);
  else if (name=="off") allOff();
  else if (name=="relax") {
    st.rgbOn=st.whiteOn=1; st.rgbColor=0x215EFF; st.rgbBrightness=32; st.whiteBrightness=17;
    st.rgbEffect=4; st.whiteEffect=0; st.speed=23; changed();
  } else if (name=="party") {
    st.rgbOn=st.whiteOn=1; st.rgbBrightness=90; st.whiteBrightness=35;
    st.rgbEffect=1; st.whiteEffect=1; st.speed=72; changed();
  } else if (name=="favorite") {
    if (prefs.getBytesLength("favorite")!=sizeof(st)) { reply(404,"Najpierw zapisz wlasna scene"); return; }
    prefs.getBytes("favorite",&st,sizeof(st)); clampState(); changed();
  } else { reply(400,"Nieznana scena"); return; }
  jsonReply(stateJSON());
}
void adminJSON() {
  if (!requireAdmin()) return;
  const esp_partition_t *next=esp_ota_get_next_update_partition(nullptr);
  String s="{\"api\":2,\"version\":"+jsonString(VERSION)+",\"token\":"+jsonString(csrfToken);
  s+=",\"rgbDrivers\":"+String(rgbDrivers)+",\"whiteDrivers\":"+String(whiteDrivers);
  s+=",\"whiteMode\":"+String(whiteMode)+",\"rgbOrder\":"+String(rgbOrder);
  s+=",\"buttonEnabled\":"+String(buttonEnabled?1:0)+",\"buttonMode\":"+String(button.mode);
  s+=",\"longOff\":"+String(button.longOff?1:0)+",\"restoreBoot\":"+String(restoreBoot?1:0);
  s+=",\"ip\":"+jsonString(currentIP())+",\"ssid\":"+jsonString(prefs.getString("ssid",""));
  s+=",\"hostname\":"+jsonString(hostname)+",\"label\":"+jsonString(deviceLabel)+",\"panelOrigin\":"+jsonString(allowedPanelOrigin)+",\"apName\":"+jsonString(apName);
  s+=",\"uptime\":"+String(millis()/1000)+",\"heap\":"+String(ESP.getFreeHeap());
  s+=",\"otaMax\":"+String(next?next->size:0)+",\"fsReady\":"+String(fsReady?1:0);
  s+=",\"fsTotal\":"+String(fsReady?LittleFS.totalBytes():0);
  s+=",\"fsUsed\":"+String(fsReady?LittleFS.usedBytes():0)+"}";
  jsonReply(s);
}
void apiConfig() {
  if (!requireWrite(true)) return;
  long rn=server.arg("rgb").toInt(), wn=server.arg("white").toInt();
  int mode=server.arg("mode").toInt(), order=server.arg("order").toInt();
  if (rn<1 || rn>MAX_DRIVERS || wn<1 || wn>MAX_DRIVERS || (mode!=1&&mode!=3) || order<0 || order>5) {
    reply(400,"Nieprawidlowa liczba ukladow, kolejnosc RGB lub tryb bialego"); return;
  }
  bool reinit=rn!=rgbDrivers || wn!=whiteDrivers || mode!=whiteMode || order!=rgbOrder;
  rgbDrivers=rn; whiteDrivers=wn; whiteMode=mode; rgbOrder=order;
  buttonEnabled=server.arg("enabled")=="1";
  button.mode=server.arg("buttonMode")=="1" ? 1:0;
  button.longOff=server.arg("longOff")=="1";
  restoreBoot=server.arg("restore")=="1";
  button.reset(digitalRead(PIN_BUTTON)==LOW,millis());
  if (reinit) configureStrips();
  changed(); saveSettings(); reply(200,"Zapisano konfiguracje");
}
void scheduleRestart() { rebootPending=true; rebootAt=millis()+1200; }
void apiWifi() {
  if (!requireWrite(true)) return;
  String ssid=server.arg("ssid"), pass=server.arg("password"), ap=server.arg("apPassword");
  if (ssid.length()>32 || pass.length()>63 || (pass.length()>0&&pass.length()<8) ||
      (ap.length()>0&&(ap.length()<8||ap.length()>63))) { reply(400,"Sprawdz SSID i dlugosc hasel"); return; }
  // A blank password keeps the saved one, unless user explicitly chooses an open network.
  if (server.arg("open")=="1") pass="";
  else if (pass.isEmpty() && !ssid.isEmpty()) pass=prefs.getString("pass","");
  prefs.putString("ssid",ssid); prefs.putString("pass",pass);
  if (!ap.isEmpty()) prefs.putString("apPass",ap);
  if (settingsDirty) saveSettings();
  reply(200,"Zapisano. Restart. Polacz telefon z odpowiednia siecia Wi-Fi."); scheduleRestart();
}
void startAccessPoint() {
  WiFi.mode(WIFI_AP); WiFi.softAP(apName.c_str(),apPassword.c_str()); accessPointMode=true; beginMDNS();
}
void startWifi() {
  WiFi.setHostname(hostname.c_str());
  // Provisioning is only offered on the local AP until an administrator is enrolled.
  if (adminPassword.length()<8) { startAccessPoint(); return; }
  String ssid=prefs.getString("ssid",""), pass=prefs.getString("pass","");
  if (ssid.isEmpty()) { startAccessPoint(); return; }
  WiFi.mode(WIFI_STA); WiFi.setSleep(false); WiFi.begin(ssid.c_str(),pass.c_str());
  uint32_t began=millis();
  while (WiFi.status()!=WL_CONNECTED && uint32_t(millis()-began)<10000) {
    pollButton();
    if (rgbDirty||whiteDirty) renderFrame(rgbDirty,whiteDirty);
    delay(5);
  }
  if (WiFi.status()==WL_CONNECTED) accessPointMode=false;
  else { WiFi.mode(WIFI_AP_STA); WiFi.softAP(apName.c_str(),apPassword.c_str()); accessPointMode=true; }
  WiFi.setAutoReconnect(true);
  beginMDNS();
}
void htmlResponse(const char *fallback, const char *path=nullptr) {
  server.sendHeader("Cache-Control","no-store");
  server.sendHeader("X-Content-Type-Options","nosniff");
  server.sendHeader("X-Frame-Options","DENY");
  if (fsReady && path && LittleFS.exists(path)) {
    File f=LittleFS.open(path,"r");
    if (f && f.size()>0 && f.size()<=MAX_HTML) { server.streamFile(f,"text/html; charset=utf-8"); f.close(); return; }
  }
  server.send_P(200,"text/html; charset=utf-8",fallback);
}
void serveSettings() {
  if (adminPassword.length()<8) { htmlResponse(SETUP_PAGE); return; }
  if (requireAdmin()) htmlResponse(SETTINGS_PAGE,"/settings.html");
}
bool canEnroll() {
  return adminPassword.length()<8 && accessPointMode && millis()<600000UL &&
         server.client().localIP()==WiFi.softAPIP();
}
void apiEnroll() {
  if (!canEnroll()) { reply(403,"Konfiguracja tylko w sieci PoolLED-Setup-xxxxxx przez 10 min od startu. Zrestartuj ESP."); return; }
  if (!requireWrite()) return;
  if (server.header("X-CSRF-Token")!=csrfToken) { reply(403,"Odswiez strone"); return; }
  String p=server.arg("password");
  if (p.length()<8||p.length()>64) { reply(400,"Haslo: od 8 do 64 znakow"); return; }
  adminPassword=p; prefs.putString("adminPass",p);
  reply(200,"Utworzono administratora. Login: admin. Otworz /settings i zaloguj sie.");
}

// A single fixed destination for each panel. No arbitrary paths can be uploaded.
File htmlFile;
String htmlDest, htmlError, htmlPrefix;
size_t htmlBytes=0, htmlExpected=0;
bool htmlOK=false, htmlSeen=false;
void failHtml(const String &reason) {
  if (htmlError.isEmpty()) htmlError=reason;
  if (htmlFile) htmlFile.close();
  if (fsReady) LittleFS.remove("/upload.tmp");
  htmlOK=false; uploadBusy=false;
}
void htmlUpload() {
  HTTPUpload &u=server.upload();
  if (u.status==UPLOAD_FILE_START) {
    // The library calls the upload callback for each part; require one file.
    if (htmlSeen) { failHtml("Przeslij jeden plik HTML"); return; }
    htmlSeen=true; htmlError=""; htmlPrefix=""; htmlBytes=0; htmlOK=false;
    if (!uploadAuthorized()) { failHtml("Brak autoryzacji"); return; }
    if (!fsReady) { failHtml("Najpierw przygotuj pamiec paneli w /service"); return; }
    String page=server.arg("page");
    htmlDest=page=="control"?"/panel.html":page=="settings"?"/settings.html":"";
    htmlExpected=server.arg("size").toInt();
    if (htmlDest.isEmpty()||!htmlExpected||htmlExpected>MAX_HTML) { failHtml("Nieprawidlowy panel lub rozmiar (maks. 96 KiB)"); return; }
    htmlFile=LittleFS.open("/upload.tmp","w");
    if (!htmlFile) { failHtml("Nie mozna utworzyc pliku tymczasowego"); return; }
    uploadBusy=true;
  } else if (u.status==UPLOAD_FILE_WRITE && htmlError.isEmpty() && htmlFile) {
    if (htmlBytes+u.currentSize>htmlExpected) { failHtml("Za duzo danych"); return; }
    if (htmlPrefix.length()<2048) {
      size_t take=2048-htmlPrefix.length(); if (take>u.currentSize) take=u.currentSize;
      htmlPrefix.concat(reinterpret_cast<const char*>(u.buf),take);
    }
    if (htmlFile.write(u.buf,u.currentSize)!=u.currentSize) { failHtml("Blad zapisu pliku"); return; }
    htmlBytes+=u.currentSize;
  } else if (u.status==UPLOAD_FILE_END && htmlError.isEmpty()) {
    if (htmlFile) htmlFile.close();
    if (htmlBytes!=htmlExpected || htmlPrefix.indexOf("name=\"poolled-api\" content=\"2\"")<0) {
      failHtml("Niepelny HTML lub brak znacznika poolled-api 2"); return;
    }
    // Commit only in the request-completion handler after exactly one complete file.
    htmlOK=true;
  } else if (u.status==UPLOAD_FILE_ABORTED) { failHtml("Przerwano wysylanie"); htmlSeen=false; }
}
void finishHtml() {
  if (!requireWrite(true)) { failHtml("Brak autoryzacji"); htmlSeen=false; return; }
  if (htmlOK && !LittleFS.rename("/upload.tmp",htmlDest.c_str())) failHtml("Nie mozna podmienic panelu");
  reply(htmlOK?200:400,htmlOK?"Panel zapisany. Odswiez strone.":htmlError.isEmpty()?"Brak pliku":htmlError);
  htmlSeen=false; htmlOK=false; uploadBusy=false; rgbDirty=whiteDirty=true;
}

// OTA validates the S3 image and application descriptor BEFORE writing anything.
// A merged 0x0 image starts with a bootloader and is therefore rejected here.
uint8_t otaHeader[288];
size_t otaHeaderUsed=0, otaExpected=0, otaBytes=0;
bool otaStarted=false, otaOK=false, otaSeen=false;
String otaError;
void failOta(const String &reason) {
  if (otaError.isEmpty()) otaError=reason;
  if (otaStarted) Update.abort();
  otaStarted=false; otaOK=false; uploadBusy=false;
}
void otaUpload() {
  HTTPUpload &u=server.upload();
  if (u.status==UPLOAD_FILE_START) {
    if (otaSeen) { failOta("Przeslij tylko jeden plik BIN"); return; }
    otaSeen=true; otaError=""; otaStarted=otaOK=false; otaHeaderUsed=otaBytes=0;
    if (!uploadAuthorized()) { failOta("Brak autoryzacji"); return; }
    const esp_partition_t *p=esp_ota_get_next_update_partition(nullptr);
    otaExpected=server.arg("size").toInt();
    if (!p||otaExpected<sizeof(otaHeader)||otaExpected>p->size) { failOta("Brak miejsca OTA. Potrzebny BIN aplikacji i dwie partycje OTA."); return; }
    uploadBusy=true;
  } else if (u.status==UPLOAD_FILE_WRITE && otaError.isEmpty() && uploadBusy) {
    if (otaBytes+u.currentSize>otaExpected) { failOta("Plik wiekszy niz zadeklarowano"); return; }
    otaBytes+=u.currentSize;
    size_t consumed=0;
    if (!otaStarted) {
      size_t n=sizeof(otaHeader)-otaHeaderUsed; if (n>u.currentSize) n=u.currentSize;
      memcpy(otaHeader+otaHeaderUsed,u.buf,n); otaHeaderUsed+=n; consumed=n;
      if (otaHeaderUsed<sizeof(otaHeader)) return;
      uint16_t chip=uint16_t(otaHeader[12])|(uint16_t(otaHeader[13])<<8);
      uint32_t descriptor=uint32_t(otaHeader[32])|(uint32_t(otaHeader[33])<<8)|
                          (uint32_t(otaHeader[34])<<16)|(uint32_t(otaHeader[35])<<24);
      if (otaHeader[0]!=0xE9||chip!=9||descriptor!=0xABCD5432) {
        failOta("To nie aplikacja ESP32-S3. NIE przesylaj merged.bin/0x0 ani bootloadera."); return;
      }
      if (!Update.begin(otaExpected,U_FLASH)) { failOta(String("OTA begin: ")+Update.errorString()); return; }
      otaStarted=true;
      if (Update.write(otaHeader,sizeof(otaHeader))!=sizeof(otaHeader)) { failOta(Update.errorString()); return; }
    }
    if (u.currentSize>consumed && Update.write(u.buf+consumed,u.currentSize-consumed)!=u.currentSize-consumed) {
      failOta(Update.errorString()); return;
    }
  } else if (u.status==UPLOAD_FILE_END && otaError.isEmpty()) {
    if (!otaStarted||otaBytes!=otaExpected) { failOta("Niepelny plik aplikacji"); return; }
    otaOK=true; // Update.end() is deferred until the complete HTTP request is accepted.
  } else if (u.status==UPLOAD_FILE_ABORTED) {
    failOta("Przerwano OTA. Poprzedni program pozostaje aktywny."); otaSeen=false;
  }
}
void finishOta() {
  if (!requireWrite(true)) { failOta("Brak autoryzacji"); otaSeen=false; return; }
  if (otaOK && !Update.end()) failOta(Update.errorString());
  bool ok=otaOK;
  otaStarted=false; uploadBusy=false;
  reply(ok?200:400,ok?"Program zapisany. ESP uruchomi sie ponownie.":otaError.isEmpty()?"Brak pliku":otaError);
  otaSeen=false; otaOK=false;
  if (ok) scheduleRestart();
}
void routes() {
  const char *headers[]={"X-PoolLED","X-CSRF-Token","Origin"}; server.collectHeaders(headers,3);
  server.on("/",HTTP_GET,[](){ htmlResponse(CONTROL_PAGE,"/panel.html"); });
  server.on("/settings",HTTP_GET,serveSettings);
  server.on("/service",HTTP_GET,[](){
    if (adminPassword.length()<8) { htmlResponse(SETUP_PAGE); return; }
    if (requireAdmin()) htmlResponse(SETTINGS_PAGE); // Never replaced by an uploaded file.
  });
  server.on("/api/state",HTTP_GET,[](){ if (acceptControlOrigin()) jsonReply(stateJSON()); });
  for (const char *path : {"/api/state","/api/set","/api/preset","/api/favorite"}) server.on(path,HTTP_OPTIONS,corsPreflight);
  server.on("/api/devices",HTTP_GET,devicesJSON);
  server.on("/api/identity",HTTP_POST,apiIdentity);
  server.on("/api/node",HTTP_POST,apiNode);
  server.on("/api/set",HTTP_POST,apiSet); server.on("/api/preset",HTTP_POST,apiPreset);
  server.on("/api/favorite",HTTP_POST,[](){
    if (!requireWrite()) return;
    if (prefs.putBytes("favorite",&st,sizeof(st))!=sizeof(st)) { reply(500,"Blad zapisu"); return; }
    reply(200,"Scena zapisana");
  });
  server.on("/api/admin",HTTP_GET,adminJSON);
  server.on("/api/config",HTTP_POST,apiConfig); server.on("/api/wifi",HTTP_POST,apiWifi);
  server.on("/api/enroll",HTTP_POST,apiEnroll);
  server.on("/api/setup",HTTP_GET,[](){
    if (!canEnroll()) { reply(403,"Konfiguracja dostepna tylko przez AP przez 10 min od restartu"); return; }
    jsonReply("{\"token\":"+jsonString(csrfToken)+"}");
  });
  server.on("/api/password",HTTP_POST,[](){
    if (!requireWrite(true)) return;
    String p=server.arg("password");
    if (p.length()<8||p.length()>64) { reply(400,"Haslo: 8-64 znakow"); return; }
    prefs.putString("adminPass",p); adminPassword=p;
    reply(200,"Haslo zmienione. Przy nastepnym zadaniu zaloguj sie nowym haslem.");
  });
  server.on("/api/fs/format",HTTP_POST,[](){
    if (!requireWrite(true)) return;
    if (server.arg("confirm")!="FORMAT") { reply(400,"Wymagane potwierdzenie FORMAT"); return; }
    LittleFS.end(); fsReady=false;
    if (!LittleFS.format()) { reply(500,"Brak partycji danych lub blad formatowania"); return; }
    fsReady=LittleFS.begin(false);
    reply(fsReady?200:500,fsReady?"Pamiec paneli gotowa. Wbudowane panele pozostaja dostepne.":"Blad montowania pamieci");
  });
  server.on("/api/ui/reset",HTTP_POST,[](){
    if (!requireWrite(true)) return;
    if (fsReady) { LittleFS.remove("/panel.html"); LittleFS.remove("/settings.html"); }
    reply(200,"Przywrocono wbudowane panele. Odswiez strone.");
  });
  server.on("/api/ui/upload",HTTP_POST,finishHtml,htmlUpload);
  server.on("/api/firmware",HTTP_POST,finishOta,otaUpload);
  server.on("/api/reboot",HTTP_POST,[](){
    if (!requireWrite(true)) return;
    if (settingsDirty) saveSettings(); reply(200,"Restart..."); scheduleRestart();
  });
  server.onNotFound([](){ reply(404,"Nie znaleziono. Sterowanie: / ; ustawienia: /settings ; panel ratunkowy: /service"); });
}
void setup() {
  Serial.begin(115200); delay(100);
  pinMode(PIN_BUTTON,INPUT_PULLUP); button.reset(digitalRead(PIN_BUTTON)==LOW,millis());
  prefs.begin("poolled",false);
  loadNetworkSettings();
  if (prefs.getBytesLength("light")==sizeof(st)) prefs.getBytes("light",&st,sizeof(st));
  rgbDrivers=prefs.getUShort("rgbN",60); whiteDrivers=prefs.getUShort("whiteN",60);
  if (rgbDrivers<1||rgbDrivers>MAX_DRIVERS) rgbDrivers=60;
  if (whiteDrivers<1||whiteDrivers>MAX_DRIVERS) whiteDrivers=60;
  whiteMode=prefs.getUChar("whiteM",1)==3?3:1;
  rgbOrder=prefs.getUChar("rgbOrder",0); if (rgbOrder>5) rgbOrder=0;
  buttonEnabled=prefs.getBool("btnEnable",true); button.mode=prefs.getUChar("btnMode",0)==1?1:0;
  button.longOff=prefs.getBool("btnLong",true); restoreBoot=prefs.getBool("restore",true);
  adminPassword=prefs.getString("adminPass",""); apPassword=prefs.getString("apPass","PoolLED2026");
  if (apPassword.length()<8||apPassword.length()>63) apPassword="PoolLED2026";
  char token[33]; snprintf(token,sizeof(token),"%08lx%08lx%08lx%08lx",(unsigned long)esp_random(),
    (unsigned long)esp_random(),(unsigned long)esp_random(),(unsigned long)esp_random()); csrfToken=token;
  clampState(); if (!restoreBoot) st.rgbOn=st.whiteOn=0;
  configureStrips(); renderFrame(true,true);
  fsReady=LittleFS.begin(false); // Never autoformat a user's uploaded pages.
  startWifi(); routes(); server.begin();
  Serial.printf("PoolLED %s: http://%s/\nSettings: /settings; rescue: /service\n",VERSION,currentIP().c_str());
}
void loop() {
  pollButton(); server.handleClient(); pollButton();
  uint32_t now=millis();
  if (!uploadBusy) {
    bool animationDue=uint32_t(now-lastFrame)>=40;
    bool r=rgbDirty||(animationDue&&st.rgbOn&&st.rgbBrightness&&st.rgbEffect);
    bool w=whiteDirty||(animationDue&&st.whiteOn&&st.whiteBrightness&&st.whiteEffect);
    if (r||w) renderFrame(r,w);
    if (animationDue) lastFrame=now;
    if (settingsDirty&&uint32_t(now-dirtyTime)>=10000) saveSettings();
  }
  if (rebootPending&&int32_t(now-rebootAt)>=0) ESP.restart();
  // Recover local control if a previously joined router disappears for a minute.
  if (!accessPointMode&&WiFi.status()!=WL_CONNECTED) {
    if (!lastReconnect) lastReconnect=now;
    if (uint32_t(now-lastReconnect)>60000) {
      WiFi.mode(WIFI_AP_STA); WiFi.softAP(apName.c_str(),apPassword.c_str()); accessPointMode=true;
    }
  } else lastReconnect=0;
  delay(1);
}
